        mat = [[0] * n for _ in range(n)]
        for u, v in graph:
            mat[u][v] = 1
            mat[v][u] = 1
        return mat

    def tensor_product(mat1, mat2):
        n = len(mat1)
        result = [[0] * (n * n) for _ in range(n * n)]
